// Existing authenticated private-bus HTTP suite; stored event DATA is not a
// native receipt, current SDK authentication or outbound WRITE reconciliation.
fn relation_event_http_config(root:&str)->serde_json::Value{let mut c=im_runtime_config_json(root);c["profile"]["relation_events"]=serde_json::json!({"group_updates":true});c}
fn insert_relation_event_http_data(db:&crate::platform::db::Database,line:&str,at:&str){
    db.with_conn(|c|c.execute("INSERT INTO app_voice_relation_events(line_id,revision,identity_key,receipt_epoch,target_hash,target_kind,base_time,update_time,fingerprint,body,updates,removals,continuity,created_at) VALUES(?1,1,zeroblob(32),?2,zeroblob(32),'group',?3,?4,zeroblob(32),?5,1,1,'gap',?6)",rusqlite::params![line,"c".repeat(32),i64::MIN,i64::MAX,b"fixture-private-relation-body".as_slice(),at]).map_err(|_|"fixture DATA only")).unwrap();
}
#[tokio::test]async fn relation_event_http_requires_auth_and_finite_query_without_current_sdk_fields(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/relation-events";
    let(status,_,body)=account_request(&served,reqwest::Method::GET,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);let cookie=authenticate(&served).await;
    for suffix in ["?limit=0","?limit=129","?limit=128&token=fixture-private","?limit=1&uid=fixture-private","?limit=1&consent=true","?limit=1&clear_unknown=true"]{let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{path}{suffix}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());assert!(state.app.app_logins.list().unwrap().is_empty());
}
#[tokio::test]async fn relation_event_http_installation_is_independent_and_cannot_infer_write_read_or_native_ready(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let good=relation_event_http_config(&cert.root);
    for mutation in [serde_json::json!({"client_ex":false}),serde_json::json!({"native_receivers":{}}),serde_json::json!({"relation_events":{"group_updates":false}}),serde_json::json!({"relation_events":{"group_updates":true,"write":true}})]{
        let mut cfg=good.clone();for(k,v)in mutation.as_object().unwrap(){cfg["profile"][k]=v.clone();}let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":cfg})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);
    }
    let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":good})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);no_store(&headers);no_secrets(&body);let line=created_line(&body);let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert_eq!(view.relation_events_supported,None);assert_eq!(view.relation_updates_supported,None);assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized);
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/relation-events?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));
    for method in [reqwest::Method::POST,reqwest::Method::DELETE,reqwest::Method::PUT]{let(status,_,body)=account_request(&served,method,&format!("/api/non-3gpp/accounts/{line}/relation-events"),Some(serde_json::json!({"accept":true,"clear_unknown":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::METHOD_NOT_ALLOWED);no_secrets(&body);}
    assert!(state.app.app_logins.list().unwrap().is_empty());
}
#[tokio::test]async fn relation_event_http_projection_preserves_signed64_gap_and_false_full_roster_without_private_target(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":relation_event_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);insert_relation_event_http_data(&state.app.database,&line,"2026-01-01T00:00:00Z");
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/relation-events?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);let data:serde_json::Value=serde_json::from_str(&body).unwrap();let row=&data["data"][0];assert_eq!(row.as_object().unwrap().len(),9);assert_eq!(row["base_time"],"-9223372036854775808");assert_eq!(row["update_time"],"9223372036854775807");assert_eq!(row["full_roster_verified"],false);assert_eq!(row["continuity"],"gap");assert_eq!(row["updates"],1);assert_eq!(row["removals"],1);
    for key in ["fixture-private-relation-body","target_hash","identity_key","receipt_epoch","fingerprint","token","nonce","grant","ready","uid"]{assert!(!body.contains(key));}
    assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");let leases:i64=state.app.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_runtime_leases",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(leases,0);
}
#[tokio::test]async fn relation_event_http_bad_stored_projection_is_not_echoed_skipped_or_used_to_clear_unknown(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":relation_event_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);insert_relation_event_http_data(&state.app.database,&line,&"private-fixture-time".repeat(256));
    state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_relation_writes(line_id,revision,user_nonce,intent_hash,identity_key,run_nonce,scope_epoch,target_kind,additions,updates,removals,state,request_id,updated_at) VALUES(?1,1,?2,zeroblob(32),zeroblob(32),?3,'fixture-old-epoch','buddy',1,0,0,0,7,'2026-01-01T00:00:00Z')",rusqlite::params![line,"a".repeat(32),"b".repeat(32)]).map_err(|_|"fixture DATA only")).unwrap();
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/relation-events?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::INTERNAL_SERVER_ERROR);no_store(&headers);no_secrets(&body);assert!(!body.contains("private-fixture-time"));let state_value:i64=state.app.database.with_conn(|c|c.query_row("SELECT state FROM app_voice_relation_writes WHERE line_id=?1",[&line],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(state_value,0);
}
